def symmetric_fill(grid, marker=8, mirror_axis=None):
    """Fill marker cells from their counterpart under the grid's mirror symmetry (vertical mirror, then horizontal mirror, then transpose).

    mirror_axis: the c in i -> c - i for the vertical mirror (and likewise for j).
    Defaults to H + 1, which matches 30x30 grids symmetric about 15.5 (a 32x32 image cropped by 2).
    """
    X = [row[:] for row in grid]
    H, W = len(X), len(X[0])
    c = (H + 1) if mirror_axis is None else mirror_axis
    out = [row[:] for row in X]
    for i in range(H):
        for j in range(W):
            if X[i][j] != marker:
                continue
            for (a, b) in ((c - 1 - i, j), (i, c - 1 - j), (j, i)):
                if 0 <= a < H and 0 <= b < W and X[a][b] != marker:
                    out[i][j] = X[a][b]
                    break
    return out
